const cmd = `
try { $p = Get-Content -Raw 'D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar\\dsh\\package.json' | ConvertFrom-Json; Write-Output ('dsh version: ' + $p.version) } catch { Write-Output ('ERR ' + $_.Exception.Message) }
